    // ── Lifecycle ──
    protected override async Task OnInitializedAsync()
    {
        _maTruongBo = await BrowserStorageService.GetMaTruongBoAsync(JS);
        _tenTruong  = await BrowserStorageService.GetItem(JS, "tenTruong") ?? "Trường học";

        await LoadAll();
    }

    private async Task LoadAll()
    {
        _isLoading = true;
        StateHasChanged();
        try
        {
            var tasks = new List<Task>
            {
                LoadThongBao(),
                LoadDanhMuc()
            };
            await Task.WhenAll(tasks);
        }
        finally
        {
            _isLoading = false;
            StateHasChanged();
        }
    }

    private async Task LoadThongBao()
    {
        try
        {
            _allList = await ThongBaoServices.hGetThongBaoChung(_maTruongBo);
            BuildPagedList();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"LoadThongBao error: {ex.Message}");
            await ShowToast("Lỗi tải danh sách thông báo!", "error");
        }
    }

    private async Task LoadDanhMuc()
    {
        try
        {
            _danhSachLop = await TruongService.hGetDanhSachLop(_maTruongBo, "", _namHoc);
            _danhSachGv  = await TruongService.hGetDanhSachGiaoVien(_maTruongBo, _namHoc);
        }
        catch (Exception ex)
        {
            Console.WriteLine($"LoadDanhMuc error: {ex.Message}");
        }
    }

    // ── Pagination Logic ──
    private void BuildPagedList()
    {
        _filteredList = _allList
            .Where(x => _filterNhomVal == 0 || x.id_nhom == _filterNhomVal)
            .Where(x => string.IsNullOrEmpty(_searchTextVal) ||
                        (x.tieu_de?.Contains(_searchTextVal, StringComparison.OrdinalIgnoreCase) == true) ||
                        (x.noi_dung?.Contains(_searchTextVal, StringComparison.OrdinalIgnoreCase) == true))
            .OrderByDescending(x => x.ngay_tao ?? DateTime.MinValue)
            .ToList();

        _pagedList = _filteredList
            .Skip((_currentPage - 1) * _pageSize)
            .Take(_pageSize)
            .ToList();
    }

    private void OnPageChanged(int page)
    {
        _currentPage = page;
        _pagedList = _filteredList
            .Skip((_currentPage - 1) * _pageSize)
            .Take(_pageSize)
            .ToList();
        StateHasChanged();
    }

    private void OnPageSizeChanged(int size)
    {
        _pageSize    = size;
        _currentPage = 1;
        BuildPagedList();
        StateHasChanged();
    }

    // ── Helpers ──
    private string GetTenNhom(int id) => _nhomOptions.FirstOrDefault(n => n.Id == id)?.Ten ?? "—";
    private string GetNhomIcon(int id) => _nhomOptions.FirstOrDefault(n => n.Id == id)?.Icon ?? "campaign";

    private string GetNhomColor(int id) => id switch
    {
        1 => "#6366f1",
        2 => "#10b981",
        3 => "#f59e0b",
        4 => "#3b82f6",
        5 => "#ec4899",
        6 => "#f43f5e",
        _ => "#64748b"
    };

    private string GetFileName(string? filepath)
    {
        if (string.IsNullOrEmpty(filepath)) return "";
        return filepath.Split('/').LastOrDefault() ?? filepath;
    }

    private string GetNhomBtnClass(int id)
        => _editDto.id_nhom == id ? "tb-nhom-btn tb-nhom-active" : "tb-nhom-btn";

    private string GetFilterChipClass(int id)
        => _filterNhom == id ? "tb-filter-chip active" : "tb-filter-chip";

    private void ClearFilepath() => _editDto.filepath = string.Empty;

    // ── Nhóm selection ──
    private void SelectNhom(int id)
    {
        _editDto.id_nhom       = id;
        _editDto.id_lop        = 0;
        _editDto.id_giao_vien  = 0;
        _editDto.ma_hoc_sinh_so = "";
        _editGvMaSo            = "";
        _filterLopForHs        = "";
        _danhSachHsSuggestion  = new();
    }

    private async Task OnFilterLopChanged()
    {
        if (string.IsNullOrEmpty(_filterLopForHs)) return;
        try
        {
            _danhSachHsSuggestion = await TruongService.hGetHocSinhByLop(_maTruongBo, _filterLopForHs, _namHoc);
        }
        catch { _danhSachHsSuggestion = new(); }
        StateHasChanged();
    }

    // ── Open/Close modal ──
    private void OpenCompose()
    {
        _editDto       = new ThongBaoChungDTO { ma_truong_bo = _maTruongBo, id_nhom = 1 };
        _editGvMaSo    = "";
        _filterLopForHs = "";
        _composeError  = "";
        _uploadError   = "";
        _danhSachHsSuggestion = new();
        _showComposeModal = true;
    }

    private void OpenEdit(ThongBaoChungDTO item)
    {
        _viewTarget    = null;
        _editDto       = new ThongBaoChungDTO
        {
            id_thong_bao_chung = item.id_thong_bao_chung,
            tieu_de    = item.tieu_de,
            noi_dung   = item.noi_dung,
            id_nhom    = item.id_nhom,
            id_lop     = item.id_lop,
            id_giao_vien = item.id_giao_vien,
            ma_hoc_sinh_so = item.ma_hoc_sinh_so,
            nguoi_gui  = item.nguoi_gui,
            filepath   = item.filepath,
            ma_truong_bo = _maTruongBo,
        };
        _editGvMaSo   = item.id_giao_vien > 0
            ? _danhSachGv.FirstOrDefault(g => g.MaSo == item.id_giao_vien.ToString())?.MaSo ?? ""
            : "";
        _composeError = "";
        _uploadError  = "";
        _showComposeModal = true;
    }

    private void OpenView(ThongBaoChungDTO item) => _viewTarget = item;

    private void CloseComposeModal() => _showComposeModal = false;

    // ── Save ──
    private async Task SaveThongBao()
    {
        _composeError = "";

        // Validate
        if (string.IsNullOrWhiteSpace(_editDto.tieu_de))
        { _composeError = "Vui lòng nhập tiêu đề!"; return; }
        if (string.IsNullOrWhiteSpace(_editDto.noi_dung))
        { _composeError = "Vui lòng nhập nội dung!"; return; }
        if (_editDto.id_nhom == 0)
        { _composeError = "Vui lòng chọn nhóm nhận!"; return; }
        if (_editDto.id_nhom == 5 && _editDto.id_lop == 0)
        { _composeError = "Vui lòng chọn lớp!"; return; }
        if (_editDto.id_nhom == 4 && string.IsNullOrEmpty(_editGvMaSo))
        { _composeError = "Vui lòng chọn giáo viên!"; return; }
        if (_editDto.id_nhom == 6 && string.IsNullOrEmpty(_editDto.ma_hoc_sinh_so))
        { _composeError = "Vui lòng chọn học sinh!"; return; }

        // Map giáo viên MaSo → id_giao_vien (dùng MaSo parse sang int nếu có)
        if (_editDto.id_nhom == 4 && !string.IsNullOrEmpty(_editGvMaSo))
        {
            if (int.TryParse(_editGvMaSo, out int gvId))
                _editDto.id_giao_vien = gvId;
            else
                _editDto.id_giao_vien = 0;
        }

        _isSaving = true;
        StateHasChanged();
        try
        {
            int savedId = await ThongBaoServices.hUpsertThongBaoChung(_editDto);
            _showComposeModal = false;
            await LoadThongBao();
            await ShowToast(_editDto.id_thong_bao_chung == 0 ? "Đã gửi thông báo thành công!" : "Đã cập nhật thông báo!", "success");
        }
        catch (Exception ex)
        {
            _composeError = "Đã xảy ra lỗi, vui lòng thử lại!";
        }
        finally
        {
            _isSaving = false;
            StateHasChanged();
        }
    }

    // ── Delete ──
    private void AskDelete(ThongBaoChungDTO item)
    {
        _viewTarget    = null;
        _deleteTarget  = item;
        _showDeleteConfirm = true;
    }

    private void CloseDeleteConfirm()
    {
        _showDeleteConfirm = false;
        _deleteTarget      = null;
    }

    private async Task ExecuteDelete()
    {
        if (_deleteTarget == null) return;
        _isSaving = true;
        StateHasChanged();
        try
        {
            await ThongBaoServices.hDeleteThongBaoChung(_deleteTarget.id_thong_bao_chung, _maTruongBo);
            _showDeleteConfirm = false;
            _deleteTarget = null;
            await LoadThongBao();
            await ShowToast("Đã xóa thông báo!", "success");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"ExecuteDelete error: {ex.Message}");
            await ShowToast("Xóa thất bại!", "error");
        }
        finally
        {
            _isSaving = false;
            StateHasChanged();
        }
    }

    // ── File Upload ──
    private async Task OnFileSelected(InputFileChangeEventArgs e)
    {
        _uploadError = "";
        var file = e.File;
        if (file == null) return;
        if (file.Size > 20 * 1024 * 1024)
        {
            _uploadError = "File quá lớn! Tối đa 20MB.";
            StateHasChanged();
            return;
        }

        _isUploading = true;
        StateHasChanged();

        try
        {
            using var ms = new System.IO.MemoryStream();
            await file.OpenReadStream(maxAllowedSize: 20 * 1024 * 1024).CopyToAsync(ms);
            ms.Position = 0;

            var client  = HttpClientFactory.CreateClient();
            var content = new MultipartFormDataContent();
            var byteArr = ms.ToArray();
            var byteContent = new ByteArrayContent(byteArr);
            byteContent.Headers.ContentType = new System.Net.Http.Headers.MediaTypeHeaderValue(file.ContentType);
            content.Add(byteContent, "file", file.Name);

            string url = $"https://nhatkyhoatdong.titkul.edu.vn/upload/media/{_maTruongBo}";
            var response = await client.PostAsync(url, content);

            if (response.IsSuccessStatusCode)
            {
                var json = await response.Content.ReadAsStringAsync();
                using var doc = System.Text.Json.JsonDocument.Parse(json);
                var root = doc.RootElement;

                if (root.TryGetProperty("error", out var errProp) && errProp.GetInt32() == 0)
                {
                    var urls = root.GetProperty("data").GetProperty("urls");
                    _editDto.filepath = urls[0].GetString() ?? "";
                    await ShowToast("Tải file lên thành công!", "success");
                }
                else
                {
                    _uploadError = "Server báo lỗi khi upload file!";
                }
            }
            else
            {
                _uploadError = $"Upload thất bại! HTTP {(int)response.StatusCode}";
            }
        }
        catch (Exception ex)
        {
            _uploadError = "Đã xảy ra lỗi, vui lòng thử lại!";
        }
        finally
        {
            _isUploading = false;
            StateHasChanged();
        }
    }

    // ── Toast ──
    private async Task ShowToast(string msg, string type = "success")
    {
        _toastCts?.Cancel();
        _toastCts     = new System.Threading.CancellationTokenSource();
        _toastMsg     = msg;
        _toastType    = type;
        _toastVisible = true;
        StateHasChanged();
        try
        {
            await Task.Delay(3500, _toastCts.Token);
            _toastVisible = false;
            StateHasChanged();
        }
        catch (TaskCanceledException) { }
    }

